    open Microsoft.Quantum.Measurement;
    open Microsoft.Quantum.Math;
    open Microsoft.Quantum.Convert;
    open Microsoft.Quantum.Arrays;

    operation QuantumGroverSearch(numQubits : Int, targetState : Int) : Int {
        mutable result = 0;

        use qubits = Qubit[numQubits];

        ApplyToEach(H, qubits);

        let iterations = Round(PI() / 4.0 * Sqrt(IntAsDouble(1 <<< numQubits)));

        for _ in 1..iterations {
            Oracle(qubits, targetState);
            DiffusionOperator(qubits);
        }

        let measurements = ForEach(M, qubits);

        for i in 0..numQubits - 1 {
            if (measurements[i] == One) {
                set result = result + (1 <<< i);
            }
        }

        ResetAll(qubits);

        return result;
    }

    operation Oracle(qubits : Qubit[], targetState : Int) : Unit {
        use ancilla = Qubit();

        X(ancilla);
        H(ancilla);

        for i in 0..Length(qubits) - 1 {
            let bit = (targetState >>> i) &&& 1;
            if (bit == 0) {
                X(qubits[i]);
            }
        }

        Controlled X(qubits, ancilla);

        for i in 0..Length(qubits) - 1 {
            let bit = (targetState >>> i) &&& 1;
            if (bit == 0) {
                X(qubits[i]);
            }
        }

        H(ancilla);
        X(ancilla);

        Reset(ancilla);
    }

    operation DiffusionOperator(qubits : Qubit[]) : Unit {
        ApplyToEach(H, qubits);
        ApplyToEach(X, qubits);

        Controlled Z(qubits[1..Length(qubits)-1], qubits[0]);

        ApplyToEach(X, qubits);
        ApplyToEach(H, qubits);
    }

    operation QuantumVQE(numQubits : Int, iterations : Int) : Double {
        mutable energy = 0.0;

        use qubits = Qubit[numQubits];

        for iter in 1..iterations {
            ApplyToEach(H, qubits);

            for i in 0..numQubits - 2 {
                CNOT(qubits[i], qubits[i + 1]);
            }

            mutable localEnergy = 0.0;
            for i in 0..numQubits - 1 {
                let measurement = Measure([PauliZ], [qubits[i]]);
                if (measurement == One) {
                    set localEnergy = localEnergy - 1.0;
                } else {
                    set localEnergy = localEnergy + 1.0;
                }
            }

            set energy = energy + localEnergy / IntAsDouble(numQubits);

            ResetAll(qubits);
        }

        return energy / IntAsDouble(iterations);
    }

    operation QuantumFourierTransform(qubits : Qubit[]) : Unit {
        let n = Length(qubits);

        for i in 0..n - 1 {
            H(qubits[i]);

            for j in i + 1..n - 1 {
                let angle = 2.0 * PI() / IntAsDouble(1 <<< (j - i + 1));
                Controlled R1([qubits[j]], (angle, qubits[i]));
            }
        }

        for i in 0..(n / 2) - 1 {
            SWAP(qubits[i], qubits[n - 1 - i]);
        }
    }

    operation QuantumPhaseEstimation(numQubits : Int) : Double {
        use register = Qubit[numQubits];
        use eigenstate = Qubit();

        X(eigenstate);

        ApplyToEach(H, register);

        for i in 0..numQubits - 1 {
            let power = 1 <<< i;
            for _ in 1..power {
                Controlled Z([register[i]], eigenstate);
            }
        }

        Adjoint QuantumFourierTransform(register);

        let measurements = ForEach(M, register);
        mutable phase = 0.0;

        for i in 0..numQubits - 1 {
            if (measurements[i] == One) {
                set phase = phase + 2.0^IntAsDouble(-i - 1);
            }
        }

        ResetAll(register);
        Reset(eigenstate);

        return phase;
    }

    operation QuantumProteinFoldingOptimization(numResidues : Int) : Int[] {
        let numQubits = numResidues * 2;
        use qubits = Qubit[numQubits];

        ApplyToEach(H, qubits);

        for i in 0..numResidues - 2 {
            CNOT(qubits[i * 2], qubits[(i + 1) * 2]);
            CNOT(qubits[i * 2 + 1], qubits[(i + 1) * 2 + 1]);
        }

        for i in 0..numResidues - 1 {
            Controlled Rz([qubits[i * 2]], (PI() / 4.0, qubits[i * 2 + 1]));
        }

        let measurements = ForEach(M, qubits);

        mutable configuration = [];
        for i in 0..numQubits - 1 {
            set configuration += [measurements[i] == One ? 1 | 0];
        }

        ResetAll(qubits);

        return configuration;
    }

    @EntryPoint()
    operation Main() : Unit {
        Message("Quantum AlphaFold3 Integration");
        Message("==============================");

        let searchResult = QuantumGroverSearch(4, 7);
        Message($"Grover Search Result: {searchResult}");

        let vqeEnergy = QuantumVQE(6, 100);
        Message($"VQE Energy: {vqeEnergy}");

        let phase = QuantumPhaseEstimation(8);
        Message($"Phase Estimation: {phase}");

        let folding = QuantumProteinFoldingOptimization(5);
        Message($"Protein Folding Configuration: {folding}");

        Message("✓ Quantum operations completed");
    }
}

